[CmdletBinding()]
param()

$ErrorActionPreference = 'Stop'
$root = Split-Path -Parent $PSScriptRoot
Set-Location $root

New-Item -ItemType Directory -Force -Path (Join-Path $root 'local') | Out-Null
$certificate = Join-Path $root 'local/caddy-root.crt'
& docker compose cp caddy:/data/caddy/pki/authorities/local/root.crt $certificate
if ($LASTEXITCODE -ne 0) { throw 'Unable to copy the local Caddy root certificate.' }

# CurrentUser avoids elevating privileges or changing the trust store for other
# Windows users. This trusts only the development CA generated by this setup.
& certutil.exe -user -addstore Root $certificate
if ($LASTEXITCODE -ne 0) { throw 'Unable to add the local Caddy CA to the Current User Root store.' }

Write-Host 'Trusted the local Caddy development CA for the current Windows user. Close and reopen the browser, then use the HTTPS MOODLE_WWWROOT from .env.'
